"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["86040"],{89213(e){e.exports=JSON.parse('{"id":"FIN-749","slug":"tax-deferred-growth","term":"Tax-Deferred Growth","also_known_as":[],"difficulty":"Intermediate","definition":"Tax-deferred growth means investment earnings, such as interest, dividends and capital gains, are not taxed as they occur, but only later, usually when money is withdrawn.","explanation":["In a normal taxable account, investors may pay tax on investment income and realized gains each year, reducing the amount left to grow. In a tax-deferred account, all earnings stay invested, so the full amount continues to compound until withdrawal.","For example, consider 10,000 invested for 20 years at 7% a year. If 25% of each year\'s return is lost to tax, the effective growth rate falls to 5.25% and the investment grows to about 27,800. If growth is tax-deferred, it grows to about 38,700. Even if 25% tax is then paid on the total gain at withdrawal, the investor keeps about 31,500, noticeably more.","Many retirement accounts and some insurance products offer tax-deferred growth. Some also provide tax relief on contributions.","The benefit of deferral is greatest over long periods and for investments with high taxable income each year. It can be even more valuable if the investor expects to be in a lower tax bracket when withdrawing money, for example in retirement.","Tax-deferred accounts usually limit access to the money before a certain age or for certain purposes, and rules differ between countries."],"note":"","total":1500,"prev":{"slug":"tax-deduction","term":"Tax Deduction"},"next":{"slug":"tax-efficient-investing","term":"Tax-Efficient Investing"}}')}}]);